// Aplatit la sortie NocoDB v3 {id, fields:{}} au format plat du noeud
// Airtable historique : {...champs, id} -> aucune expression aval a changer.
return $input.all().map(i => ({ json: { ...(i.json.fields || {}), id: i.json.id } }));

// runOnceForEachItem — parse Gemini, émet 1 item avec Texte + Hashtags + id pour update
const resp = $input.item.json;
const src = $('Airtable — Lire planifiés').all()[$itemIndex].json;
let text = '';
if (resp.candidates?.[0]?.content?.parts) text = resp.candidates[0].content.parts.map(p=>p.text||'').join('');
else if (typeof resp === 'string') text = resp;
else text = JSON.stringify(resp);
function extractJson(t){let c=(t||'').trim().replace(/^```(?:json)?\s*/i,'').replace(/```\s*$/i,'').trim();try{return JSON.parse(c);}catch(e){}const m=c.match(/\{[\s\S]*\}/);if(m){try{return JSON.parse(m[0]);}catch(e){}}return null;}
const data = extractJson(text) || {};
return { json: {
  id: src.id,
  Texte: data.Texte || '',
  Hashtags: data.Hashtags || '',
  Slides_JSON: (data.Slides && Array.isArray(data.Slides) && data.Slides.length) ? JSON.stringify(data.Slides) : '',
  Status: 'rédigé'
}};
